function serverTimingHeader(entries = {}) {
  return Object.entries(entries)
    .filter(([, duration]) => Number.isFinite(duration) && duration >= 0)
    .map(([name, duration]) => `${name};dur=${duration.toFixed(1)}`)
    .join(", ");
}

export function parseWorkspaceNavigationUrl(input, base = "http://127.0.0.1/") {
  const url = new URL(String(input || ""), base);
  const clean = (key, limit = 4_000) => String(url.searchParams.get(key) || "").trim().slice(0, limit);
  const requestedView = clean("view", 80);
  const graphCamera = clean("graphCamera", 120).split(",").map(Number);
  const navigation = {
    workspaceId: /^[A-Za-z0-9_-]{8,120}$/.test(clean("workspace", 120)) ? clean("workspace", 120) : "",
    projectId: clean("project", 240),
    view: ["hub", "file", "settings", "proposal", "new-doc", "project-manager", "codex-prompts", "graph"].includes(requestedView) ? requestedView : "hub",
    folder: clean("folder"),
    search: clean("search", 300),
    file: clean("file"),
    proposal: clean("proposal"),
    settingsSection: clean("settings", 120),
    explorerDocumentView: clean("explorerView", 20) === "related" ? "related" : "location",
    graphScope: ["global", "project", "local"].includes(clean("graphScope", 40)) ? clean("graphScope", 40) : "global",
    graphDepth: Math.min(3, Math.max(1, Number(clean("graphDepth", 4)) || 1)),
    graphLayers: clean("graphLayers", 240).split(",").filter(Boolean),
    graphTypes: clean("graphTypes", 240).split(",").filter(Boolean),
    graphRelations: clean("graphRelations", 240).split(",").filter(Boolean),
    graphNode: clean("graphNode", 1_000),
    graphIncludeUnresolved: clean("graphUnresolved", 2) === "1",
    graphShowOrphans: clean("graphOrphans", 2) !== "0",
    graphShowArrows: clean("graphArrows", 2) === "1",
    graphCamera: graphCamera.length === 3 && graphCamera.every(Number.isFinite)
      ? { x: graphCamera[0], y: graphCamera[1], scale: Math.min(3.5, Math.max(0.45, graphCamera[2])) }
      : { x: 0, y: 0, scale: 1 },
  };
  Object.defineProperties(navigation, {
    proposalRepositoryId: { value: clean("repositoryId", 1_000), enumerable: false },
    proposalHead: { value: clean("proposalHead", 160), enumerable: false },
  });
  return navigation;
}

export function workspaceReloadCircuitDecision(rawValue, now = Date.now(), windowMs = 5_000) {
  let timestamps = [];
  try {
    const parsed = JSON.parse(String(rawValue || "[]"));
    if (Array.isArray(parsed)) timestamps = parsed.filter((value) => Number.isFinite(value) && now - value >= 0 && now - value < windowMs);
  } catch {}
  const allowed = timestamps.length === 0;
  return { allowed, value: JSON.stringify(allowed ? [...timestamps, now] : timestamps) };
}

export function shouldReplaceDuplicatedWorkspaceIdentity({ message, requestedWorkspaceId, clientInstanceId, alreadyResolved = false } = {}) {
  return !alreadyResolved
    && message?.type === "workspace-conflict"
    && message.workspaceId === requestedWorkspaceId
    && message.requester === clientInstanceId;
}

export function contextRoomProjectResponseAction({ expectedProjectId = "", responseProjectId = "", globalRoom = true } = {}) {
  if (!expectedProjectId && responseProjectId) return "initialize";
  if (!responseProjectId || responseProjectId === expectedProjectId) return "accept";
  return globalRoom ? "refresh-in-place" : "exceptional-reload";
}

