          publicHost: remoteWorkspaceAccess.publicHost,
          secret: remoteWorkspaceAccess.secret,
          issuer: remoteWorkspaceAccess.issuer,
          agent: { ...agent, sessionId: requestedSessionId || agent.sessionId || "" },
