function settingsDisclosureIsOpen(id) {
  if (Object.prototype.hasOwnProperty.call(state.settingsDisclosureState || {}, id)) return state.settingsDisclosureState[id];
  return SETTINGS_DISCLOSURE_DEFAULTS[id] !== false;
}

function renderSettingsDisclosure({ id, title, copy, status = "", scope = "", body = "", trackDirty = false } = {}) {
  const safeId = SETTINGS_DISCLOSURE_IDS.includes(id) ? id : slugifyUiId(id || title);
  const open = settingsDisclosureIsOpen(safeId) ? " open" : "";
  const dirtyGroup = trackDirty ? ' data-settings-dirty-group="' + escapeHtml(safeId) + '"' : "";
  return '<details id="settings-group-' + escapeHtml(safeId) + '" class="settings-disclosure" data-settings-disclosure="' + escapeHtml(safeId) + '"' + dirtyGroup + open + '>'
    + '<summary><span class="settings-disclosure-chevron" aria-hidden="true"><span>›</span></span>'
    + '<span class="settings-disclosure-summary"><strong>' + escapeHtml(title) + '</strong><span>' + escapeHtml(copy) + '</span></span>'
    + '<span class="settings-disclosure-status">' + escapeHtml([status, scope].filter(Boolean).join(" · ")) + '</span></summary>'
    + '<div class="settings-disclosure-body">' + body + '</div></details>';
}

function wireSettingsDisclosures(root) {
  root.querySelectorAll("[data-settings-disclosure]").forEach((details) => details.addEventListener("toggle", () => {
    state.settingsDisclosureState[details.dataset.settingsDisclosure] = details.open;
    scheduleSessionStatePush();
  }));
}

function settingsGroupSignature(group) {
  return JSON.stringify([...group.querySelectorAll("input, select, textarea")].map((control, index) => ({
    key: control.id || control.name || control.dataset.shortcut || index,
    type: control.type || control.tagName,
    value: control.type === "checkbox" || control.type === "radio" ? control.checked : control.dataset.shortcut ?? control.value,
  })));
}

function updateSettingsSaveState() {
  const count = state.settingsDirtyGroups.size;
  const holder = el("settingsSaveState");
  const button = el("saveSettings");
  if (holder) {
    holder.dataset.dirty = String(count > 0);
    holder.innerHTML = count
      ? '<strong>Unsaved changes</strong><span>' + count + ' setting group' + (count === 1 ? '' : 's') + ' changed</span>'
      : '<strong>All changes saved</strong><span>Project settings and global preferences are up to date.</span>';
  }
  const selected = selectedGlobalProjectSettingsContext();
  const validating = Boolean(selected.key && selected.payload && !state.globalProjectSettingsValidated.has(selected.key));
  if (button) button.disabled = count === 0 || validating;
}

function refreshSettingsDirtyGroup(group) {
  const id = group?.dataset.settingsDirtyGroup;
  if (!id || !state.settingsBaselineByGroup.has(id)) return;
  if (settingsGroupSignature(group) === state.settingsBaselineByGroup.get(id)) state.settingsDirtyGroups.delete(id);
  else state.settingsDirtyGroups.add(id);
  updateSettingsSaveState();
}

function wireSettingsDirtyTracking(root) {
  state.settingsBaselineByGroup = new Map();
  state.settingsDirtyGroups.clear();
  root.querySelectorAll("[data-settings-dirty-group]").forEach((group) => state.settingsBaselineByGroup.set(group.dataset.settingsDirtyGroup, settingsGroupSignature(group)));
  const refreshFromEvent = (event) => {
    const group = event.target.closest?.("[data-settings-dirty-group]");
    if (group) refreshSettingsDirtyGroup(group);
  };
  root.addEventListener("input", refreshFromEvent);
  root.addEventListener("change", refreshFromEvent);
  root.addEventListener("click", (event) => {
    const group = event.target.closest?.("[data-settings-dirty-group]");
    if (group) requestAnimationFrame(() => refreshSettingsDirtyGroup(group));
  });
  updateSettingsSaveState();
}

function normalizedSettingsSearch(value) {
  return String(value || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function settingsSectionLabel(sectionId) {
  const labels = {
    project: "Project",
    "review-trust": "Review and trust",
    "agent-environment": "Agent environment",
    preferences: "Preferences",
    "advanced-extensions": "Advanced extensions",
  };
  return labels[normalizeSettingsSectionId(sectionId)] || "Settings";
}

function matchingSettingsSearchItems(query) {
  const terms = normalizedSettingsSearch(query).split(" ").filter(Boolean);
  if (!terms.length) return [];
  return SETTINGS_SEARCH_ITEMS.map((item) => {
    const haystack = normalizedSettingsSearch([item.label, item.description, item.section, item.scope, item.keywords].join(" "));
    if (!terms.every((term) => haystack.includes(term))) return null;
    const label = normalizedSettingsSearch(item.label);
    const score = terms.reduce((total, term) => total + (label.startsWith(term) ? 5 : label.includes(term) ? 3 : 1), 0);
    return { ...item, score };
  }).filter(Boolean).sort((a, b) => b.score - a.score || a.label.localeCompare(b.label)).slice(0, 8);
}

function renderSettingsSearchResults() {
  const input = el("settingsSearch");
  const results = el("settingsSearchResults");
  const status = el("settingsSearchStatus");
  if (!input || !results) return;
  const items = matchingSettingsSearchItems(state.settingsSearchQuery);
  state.settingsSearchIndex = items.length ? Math.max(0, Math.min(state.settingsSearchIndex, items.length - 1)) : -1;
  results.hidden = !state.settingsSearchQuery;
  input.setAttribute("aria-expanded", String(Boolean(state.settingsSearchQuery)));
  if (!state.settingsSearchQuery) {
    results.innerHTML = "";
    input.removeAttribute("aria-activedescendant");
    if (status) status.textContent = "";
    return;
  }
  results.innerHTML = items.length
    ? items.map((item, index) => '<button id="settings-search-result-' + escapeHtml(item.id) + '" class="settings-search-result" type="button" role="option" aria-selected="' + String(index === state.settingsSearchIndex) + '" data-settings-search-result="' + escapeHtml(item.id) + '"><strong>' + escapeHtml(item.label) + '</strong><span class="settings-search-result-meta">' + escapeHtml(settingsSectionLabel(item.section) + ' · ' + item.scope) + '</span><p>' + escapeHtml(item.description) + '</p></button>').join("")
    : '<div class="settings-search-empty">No settings found. Try a familiar word such as “skills”, “review”, or “sound”.</div>';
  if (items.length) input.setAttribute("aria-activedescendant", "settings-search-result-" + items[state.settingsSearchIndex].id);
  else input.removeAttribute("aria-activedescendant");
  if (status) status.textContent = items.length + " setting result" + (items.length === 1 ? "" : "s");
}

function openSettingsSearchItem(itemId) {
  const item = SETTINGS_SEARCH_ITEMS.find((candidate) => candidate.id === itemId);
  if (!item) return;
  activateSettingsSection(item.section, { resetScroll: false });
  const disclosure = document.querySelector('[data-settings-disclosure="' + item.group + '"]');
  if (disclosure) {
    disclosure.open = true;
    state.settingsDisclosureState[item.group] = true;
    disclosure.classList.remove("is-search-target");
    requestAnimationFrame(() => disclosure.classList.add("is-search-target"));
  }
  const target = (item.target ? el(item.target) : null) || disclosure?.querySelector("summary");
  const opensHelpDialog = Boolean(target?.matches("[data-settings-help-trigger]"));
  if (opensHelpDialog) target.click();
  requestAnimationFrame(() => {
    if (!opensHelpDialog) {
      target?.scrollIntoView({ behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "center" });
      target?.focus({ preventScroll: true });
    }
    const status = el("settingsSearchStatus");
    if (status) status.textContent = "Opened " + item.label;
  });
  el("settingsSearchResults").hidden = true;
  el("settingsSearch").setAttribute("aria-expanded", "false");
  el("settingsSearch").removeAttribute("aria-activedescendant");
  scheduleSessionStatePush();
}

function wireSettingsSearch() {
  const input = el("settingsSearch");
  const results = el("settingsSearchResults");
  if (!input || !results) return;
  input.value = state.settingsSearchQuery;
  if (input.dataset.wired === "true") {
    renderSettingsSearchResults();
    return;
  }
  input.dataset.wired = "true";
  input.addEventListener("input", () => {
    state.settingsSearchQuery = input.value;
    state.settingsSearchIndex = 0;
    renderSettingsSearchResults();
  });
  input.addEventListener("keydown", (event) => {
    const items = matchingSettingsSearchItems(state.settingsSearchQuery);
    if (event.key === "Escape") {
      results.hidden = true;
      input.setAttribute("aria-expanded", "false");
      input.removeAttribute("aria-activedescendant");
      return;
    }
    if (!items.length) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const direction = event.key === "ArrowDown" ? 1 : -1;
      state.settingsSearchIndex = (state.settingsSearchIndex + direction + items.length) % items.length;
      renderSettingsSearchResults();
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      openSettingsSearchItem(items[Math.max(0, state.settingsSearchIndex)]?.id);
    }
  });
  input.addEventListener("focus", renderSettingsSearchResults);
  results.addEventListener("mousedown", (event) => event.preventDefault());
  results.addEventListener("click", (event) => openSettingsSearchItem(event.target.closest("[data-settings-search-result]")?.dataset.settingsSearchResult));
  if (!state.settingsSearchDismissWired) {
    state.settingsSearchDismissWired = true;
    document.addEventListener("click", (event) => {
      if (event.target.closest("[data-settings-search]")) return;
      const activeResults = el("settingsSearchResults");
      const activeInput = el("settingsSearch");
      if (activeResults) activeResults.hidden = true;
      activeInput?.setAttribute("aria-expanded", "false");
      activeInput?.removeAttribute("aria-activedescendant");
    });
  }
  renderSettingsSearchResults();
}

function activateSettingsSection(sectionId, options = {}) {
  const next = normalizeSettingsSectionId(sectionId);
  const visiblePanels = new Set(SETTINGS_SECTION_GROUPS[next] || []);
  state.settingsSection = next;
  document.querySelectorAll("[data-settings-section-target]").forEach((tab) => {
    const active = tab.dataset.settingsSectionTarget === next;
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
  });
  document.querySelectorAll("[data-settings-section-panel]").forEach((panel) => {
    panel.hidden = !visiblePanels.has(panel.dataset.settingsSectionPanel);
  });
  if (next === "agent-environment") {
    const selected = selectedGlobalProjectSettingsContext();
    const projectId = selected.worktree?.id || "";
    const cacheKey = projectId || "__current__";
    if (!state.sharedSkillLocations.has(cacheKey)) void loadSharedSkillLocations({ projectId }).catch((error) => setStatus(error.message));
  }
  if (options.resetScroll !== false) el("settingsPage").scrollTop = 0;
  if (options.focus) document.querySelector('[data-settings-section-target="' + next + '"]')?.focus();
  scheduleSessionStatePush();
}

function wireSettingsTabs(root) {
  const tabs = [...root.querySelectorAll("[data-settings-section-target]")];
  tabs.forEach((tab, index) => {
    if (tab.dataset.settingsTabWired === "true") return;
    tab.dataset.settingsTabWired = "true";
    tab.addEventListener("click", () => activateSettingsSection(tab.dataset.settingsSectionTarget));
    tab.addEventListener("keydown", (event) => {
      let targetIndex = null;
      if (["ArrowRight", "ArrowDown"].includes(event.key)) targetIndex = (index + 1) % tabs.length;
      if (["ArrowLeft", "ArrowUp"].includes(event.key)) targetIndex = (index - 1 + tabs.length) % tabs.length;
      if (event.key === "Home") targetIndex = 0;
      if (event.key === "End") targetIndex = tabs.length - 1;
      if (targetIndex == null) return;
      event.preventDefault();
      activateSettingsSection(tabs[targetIndex].dataset.settingsSectionTarget, { focus: true });
    });
  });
}

function renderSettingsThemePreview(themeId = currentFileThemeId()) {
  return '<div class="settings-theme-preview" aria-label="Document theme preview">' +
    '<div class="settings-theme-preview-head"><span>Document preview</span><code id="settingsThemePreviewName">' + escapeHtml(themeId) + '</code></div>' +
    '<div class="doc-editor markdown-view">' + renderMarkdownLines(SETTINGS_THEME_PREVIEW_DOC) + '</div>' +
  '</div>';
}

function codexReferenceLineNumber(text, offset) {
  const value = String(text || "");
  const safeOffset = Math.max(0, Math.min(Number(offset) || 0, value.length));
  return value.slice(0, safeOffset).split("\n").length;
}

function codexReferenceLineRange(text, selectionStart, selectionEnd) {
  const value = String(text || "");
  const start = Math.max(0, Math.min(Number(selectionStart) || 0, value.length));
  const end = Math.max(start, Math.min(Number(selectionEnd) || 0, value.length));
  if (start === end) return null;
  return {
    startLine: codexReferenceLineNumber(value, start),
    endLine: codexReferenceLineNumber(value, Math.max(start, end - 1)),
  };
}

function codexReferenceLineLabel(startLine = 1, endLine = startLine) {
  return startLine === endLine ? "L" + startLine : "L" + startLine + "\u2013" + endLine;
}

function buildCompactCodexReferenceText({ path = "", startLine = 1, endLine = startLine, text = "", dirty = false } = {}) {
  const prefix = "@" + path + " " + codexReferenceLineLabel(startLine, endLine);
  if (!dirty) return prefix + " ";
  const quote = String(text || "").replace(/\r\n?/g, "\n").split("\n").map((line) => "> " + line).join("\n");
  return prefix + " · unsaved" + (quote ? "\n" + quote : "") + "\n";
}

function currentCodexReferencePath() {
  return state.selectedStartupContext?.displayPath || state.selected || "";
}

function editorCodexReferenceSelection() {
  if (state.page !== "file") return null;
  const editor = el("docEditor");
  if (!editor || typeof editor.selectionStart !== "number" || editor.selectionStart === editor.selectionEnd) return null;
  const lineRange = codexReferenceLineRange(editor.value, editor.selectionStart, editor.selectionEnd);
  const text = editor.value.slice(editor.selectionStart, editor.selectionEnd);
  if (!lineRange || !text.trim()) return null;
  return { path: currentCodexReferencePath(), text, dirty: editor.value !== state.saved, ...lineRange };
}

function collectCodexReferenceSelection() {
  return editorCodexReferenceSelection();
}

function currentCodexReferenceShortcut() {
  return state.settings?.shortcuts?.codexReference ?? DEFAULT_CODEX_REFERENCE_SHORTCUT;
}

function formatShortcutForPlatform(shortcut = "") {
  const parts = String(shortcut || "").split("+").filter(Boolean);
  if (!parts.length) return "";
  if (!isMacPlatform()) return parts.map((part) => part === "Mod" ? "Ctrl" : part).join("+");
  const labels = { Mod: "\u2318", Meta: "\u2318", Ctrl: "\u2303", Alt: "\u2325", Shift: "\u21e7", Enter: "\u21b5", Space: "Space", Backspace: "\u232b", Delete: "\u2326", ArrowUp: "\u2191", ArrowDown: "\u2193", ArrowLeft: "\u2190", ArrowRight: "\u2192", PageUp: "PgUp", PageDown: "PgDn" };
  return parts.map((part) => labels[part] || part).join("");
}

function keyboardShortcutFromEvent(event) {
  if (["Meta", "Control", "Alt", "Shift"].includes(event.key)) return "";
  const modifiers = [];
  if (event.metaKey || (!isMacPlatform() && event.ctrlKey)) modifiers.push("Mod");
  if (isMacPlatform() && event.ctrlKey) modifiers.push("Ctrl");
  if (event.altKey) modifiers.push("Alt");
  if (event.shiftKey) modifiers.push("Shift");
  if (!modifiers.some((modifier) => ["Mod", "Ctrl", "Alt"].includes(modifier))) return "";
  let key = String(event.key || "");
  if (key === " ") key = "Space";
  else if (key.length === 1) key = key.toUpperCase();
  const allowed = /^[A-Z0-9]$/.test(key) || ["Enter", "Space", "Backspace", "Delete", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Home", "End", "PageUp", "PageDown"].includes(key);
  return allowed ? [...modifiers, key].join("+") : "";
}

function keyboardEventMatchesShortcut(event, shortcut = "") {
  const expected = String(shortcut || "");
  return Boolean(expected) && keyboardShortcutFromEvent(event) === expected;
}

function handleCodexReferenceShortcut(event) {
  if (!keyboardEventMatchesShortcut(event, currentCodexReferenceShortcut())) return false;
  if (!collectCodexReferenceSelection()) return false;
  event.preventDefault();
  event.stopPropagation();
  referenceCodexSelectionInCurrentTask().catch(() => {
    showCodexReferenceActionFeedback("Failed");
    setStatus("could not reference the selection or copy it to the clipboard");
  });
  return true;
}

function markdownReferenceSelectionRect(editor) {
  const start = markdownEditorDomPosition(editor.selectionStart);
  const end = markdownEditorDomPosition(editor.selectionEnd);
  if (!start || !end) return null;
  const range = document.createRange();
  range.setStart(start.node, start.offset);
  range.setEnd(end.node, end.offset);
  const editorRect = editor.getBoundingClientRect();
  return [...range.getClientRects()].find((rect) => rect.height > 0 && rect.bottom >= editorRect.top && rect.top <= editorRect.bottom) || range.getBoundingClientRect();
}

function plainTextReferenceSelectionRect(editor) {
  const styles = getComputedStyle(editor);
  const editorRect = editor.getBoundingClientRect();
  const mirror = document.createElement("div");
  const marker = document.createElement("span");
  mirror.setAttribute("aria-hidden", "true");
  Object.assign(mirror.style, {
    position: "fixed",
    visibility: "hidden",
    pointerEvents: "none",
    zIndex: "-1",
    left: (editorRect.left - editor.scrollLeft) + "px",
    top: (editorRect.top - editor.scrollTop) + "px",
    width: editorRect.width + "px",
    minHeight: editorRect.height + "px",
    boxSizing: styles.boxSizing,
    padding: styles.padding,
    border: styles.border,
    font: styles.font,
    letterSpacing: styles.letterSpacing,
    lineHeight: styles.lineHeight,
    tabSize: styles.tabSize,
    whiteSpace: "pre-wrap",
    overflowWrap: styles.overflowWrap || "break-word",
  });
  mirror.append(document.createTextNode(editor.value.slice(0, editor.selectionStart)));
  marker.textContent = "\u200b";
  mirror.append(marker);
  document.body.appendChild(mirror);
  const rect = marker.getBoundingClientRect();
  mirror.remove();
  return rect.top >= editorRect.top - 2 && rect.top <= editorRect.bottom + 2 ? rect : null;
}

function codexReferenceSelectionRect() {
  const editor = el("docEditor");
  if (!editor) return null;
  return el("docHighlighter") ? markdownReferenceSelectionRect(editor) : plainTextReferenceSelectionRect(editor);
}

function positionCodexReferenceAction() {
  const action = el("codexReferencePopover");
  if (!action || action.hidden) return;
  const rect = codexReferenceSelectionRect();
  if (!rect || !Number.isFinite(rect.left) || !Number.isFinite(rect.top)) {
    action.hidden = true;
    return;
  }
  const margin = 10;
  const gap = 8;
  const width = action.offsetWidth;
  const height = action.offsetHeight;
  const center = rect.left + Math.max(1, rect.width) / 2;
  const editorRect = el("docEditor")?.getBoundingClientRect();
  const minimumLeft = Math.max(margin, (editorRect?.left || 0) + 8);
  const maximumLeft = Math.min(window.innerWidth - width - margin, (editorRect?.right || window.innerWidth) - width - 8);
  action.style.left = Math.max(minimumLeft, Math.min(maximumLeft, center - width / 2)) + "px";
  const above = rect.top - height - gap;
  action.style.top = (above >= margin ? above : Math.min(window.innerHeight - height - margin, rect.bottom + gap)) + "px";
}

function updateCodexReferenceAction() {
  const action = el("codexReferencePopover");
  if (!action) return;
  const reference = collectCodexReferenceSelection();
  if (!reference) {
    action.hidden = true;
    return;
  }
  const lines = codexReferenceLineLabel(reference.startLine, reference.endLine);
  action.querySelector("[data-codex-reference-line]").textContent = lines;
  const shortcut = formatShortcutForPlatform(currentCodexReferenceShortcut());
  const shortcutLabel = action.querySelector("[data-codex-reference-shortcut]");
  shortcutLabel.textContent = shortcut;
  shortcutLabel.hidden = !shortcut;
  action.title = "Add @" + reference.path + " " + lines + " to the active Codex composer. Nothing is sent.";
  action.hidden = false;
  positionCodexReferenceAction();
}

function scheduleCodexReferenceActionUpdate() {
  if (codexReferenceFrame) return;
  codexReferenceFrame = window.requestAnimationFrame(() => {
    codexReferenceFrame = 0;
    updateCodexReferenceAction();
  });
}

function showCodexReferenceActionFeedback(message) {
  const action = el("codexReferencePopover");
  if (!action) return;
  const line = action.querySelector("[data-codex-reference-line]");
  if (line) line.textContent = message;
  if (codexReferenceFeedbackTimer) window.clearTimeout(codexReferenceFeedbackTimer);
  codexReferenceFeedbackTimer = window.setTimeout(() => {
    codexReferenceFeedbackTimer = 0;
    updateCodexReferenceAction();
  }, 2_400);
}

async function copyCodexReferenceText(text) {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const fallback = document.createElement("textarea");
  fallback.value = text;
  fallback.setAttribute("readonly", "");
  fallback.style.position = "fixed";
  fallback.style.opacity = "0";
  fallback.style.pointerEvents = "none";
  document.body.appendChild(fallback);
  let copied = false;
  try {
    fallback.select();
    copied = document.execCommand("copy");
  } finally {
    fallback.remove();
  }
  if (!copied) throw new Error("Clipboard copy failed.");
}

async function copyAgentCliInstructions(button) {
  const prompt = button?.closest("[data-settings-disclosure]")?.querySelector("[data-agent-cli-prompt]")?.textContent || AGENT_CLI_HANDOFF_PROMPT;
  await copyCodexReferenceText(prompt);
  const previous = button.textContent;
  button.textContent = "Copied";
  setStatus("Agent CLI instructions copied");
  window.setTimeout(() => { if (button.isConnected) button.textContent = previous; }, 1_800);
}

async function referenceCodexSelectionInCurrentTask() {
  const reference = collectCodexReferenceSelection();
  if (!reference) {
    setStatus("select text before creating a Codex reference");
    return;
  }
  const fallbackText = buildCompactCodexReferenceText(reference);
  try {
    const result = await api("/api/codex/reference", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        path: reference.path,
        startLine: reference.startLine,
        endLine: reference.endLine,
        dirty: reference.dirty,
        selectedText: reference.dirty ? reference.text : "",
      }),
    });
    showCodexReferenceActionFeedback(result.nativeMention ? "Linked" : "Added");
    setStatus((result.nativeMention ? "file linked" : "reference added") + " in the active Codex composer · review it before sending");
  } catch (error) {
    await copyCodexReferenceText(fallbackText);
    showCodexReferenceActionFeedback("Copied");
    setStatus((error?.message || "Codex composer bridge unavailable") + " · reference copied instead");
  }
}

function applyContextHubAttentionState(attention) {
  if (!state.contextHub || !attention) return;
  state.contextHubMutationGeneration += 1;
  state.contextHub.attention = attention;
  const ranks = new Map((attention.projectOrder || []).map((id, index) => [id, index]));
  state.contextHub.projects = (state.contextHub.projects || []).map((project) => ({
    ...project,
    priorityRank: ranks.has(project.priorityId) ? ranks.get(project.priorityId) : null,
  }));
}

function projectPriorityProjects() {
  return contextHubPrioritizedProjects(state.contextHub?.projects || []);
}

function renderProjectPrioritySettings() {
  const allProjects = projectPriorityProjects();
  const needle = state.projectPrioritySearch.trim().toLowerCase();
  const projects = allProjects.filter((project) => !needle || contextHubProjectSearchText(project).includes(needle));
  const rows = projects.map((project) => {
    const rank = allProjects.findIndex((item) => item.priorityId === project.priorityId);
    const disabled = state.projectPriorityBusy ? " disabled" : "";
    return '<div class="project-priority-row" draggable="true" data-project-priority-id="' + escapeHtml(project.priorityId || "") + '">'
      + '<span class="project-priority-handle" aria-hidden="true">⋮⋮</span>'
      + '<span class="project-priority-rank">' + (rank + 1) + '</span>'
      + '<span class="project-priority-copy"><strong>' + escapeHtml(project.title || project.id) + '</strong><small>' + escapeHtml(contextHubProjectPickerLocation(project)) + '</small></span>'
      + '<span class="project-priority-actions">'
      + '<button type="button" data-project-priority-action="top" title="Move to top"' + (rank <= 0 ? " disabled" : disabled) + '>⇡</button>'
      + '<button type="button" data-project-priority-action="up" title="Move up"' + (rank <= 0 ? " disabled" : disabled) + '>↑</button>'
      + '<button type="button" data-project-priority-action="down" title="Move down"' + (rank >= allProjects.length - 1 ? " disabled" : disabled) + '>↓</button>'
      + '<button type="button" data-project-priority-action="bottom" title="Move to bottom"' + (rank >= allProjects.length - 1 ? " disabled" : disabled) + '>⇣</button>'
      + '</span></div>';
  }).join("");
  return '<div class="project-priority-editor">'
    + '<div class="settings-body-toolbar"><span>Projects, worktrees, and their reviews follow this device-wide order.</span><button class="secondary" type="button" data-project-priority-reset' + (state.projectPriorityBusy ? " disabled" : "") + '>Reset automatic order</button></div>'
    + '<input class="project-priority-search" type="search" value="' + escapeHtml(state.projectPrioritySearch) + '" placeholder="Search projects…" aria-label="Search projects to prioritize" />'
    + '<div class="project-priority-list">' + (rows || '<div class="settings-empty-state">No project matches this search.</div>') + '</div>'
    + '<p class="settings-help">Conflicts still surface first for safety. Changing this order never changes documentation, reviews, or shared Git history.</p>'
    + '</div>';
}

async function saveProjectPriorityOrder(projectOrder) {
  if (state.projectPriorityBusy) return;
  state.projectPriorityBusy = true;
  renderSettingsPanel();
  try {
    const attention = await api("/api/context-hub/project-order", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ projectOrder, expectedRevision: state.contextHub?.attention?.revision || "" }),
    });
    applyContextHubAttentionState(attention);
    workspaceUpdate("catalog-refreshed");
    setStatus(projectOrder.length ? "project priority updated" : "automatic project ordering restored");
  } finally {
    state.projectPriorityBusy = false;
    renderGlobalProjectExplorer();
    renderContextRoomGlobalReviewQueue();
    renderSettingsPanel();
  }
}

function moveProjectPriority(priorityId, action, explicitBefore = "") {
  const order = projectPriorityProjects().map((project) => project.priorityId).filter(Boolean);
  const index = order.indexOf(priorityId);
  if (index < 0) return;
  order.splice(index, 1);
  let nextIndex = action === "top" ? 0
    : action === "bottom" ? order.length
      : action === "up" ? Math.max(0, index - 1)
        : action === "down" ? Math.min(order.length, index + 1)
          : explicitBefore ? Math.max(0, order.indexOf(explicitBefore))
            : index;
  if (explicitBefore && order.indexOf(explicitBefore) < 0) nextIndex = order.length;
  order.splice(nextIndex, 0, priorityId);
  saveProjectPriorityOrder(order).catch((error) => setStatus(error.message));
}

function wireProjectPrioritySettings(root) {
  const search = root.querySelector(".project-priority-search");
  search?.addEventListener("input", (event) => {
    state.projectPrioritySearch = event.target.value;
    renderSettingsPanel();
    window.requestAnimationFrame(() => {
      const next = document.querySelector(".project-priority-search");
      next?.focus();
      next?.setSelectionRange(next.value.length, next.value.length);
    });
  });
  root.querySelector("[data-project-priority-reset]")?.addEventListener("click", () => saveProjectPriorityOrder([]).catch((error) => setStatus(error.message)));
  root.querySelectorAll("[data-project-priority-action]").forEach((button) => button.addEventListener("click", () => {
    const row = button.closest("[data-project-priority-id]");
    moveProjectPriority(row?.dataset.projectPriorityId || "", button.dataset.projectPriorityAction);
  }));
  let dragged = "";
  root.querySelectorAll("[data-project-priority-id]").forEach((row) => {
    row.addEventListener("dragstart", (event) => { dragged = row.dataset.projectPriorityId || ""; event.dataTransfer.effectAllowed = "move"; });
    row.addEventListener("dragover", (event) => { if (dragged && dragged !== row.dataset.projectPriorityId) event.preventDefault(); });
    row.addEventListener("drop", (event) => { event.preventDefault(); if (dragged) moveProjectPriority(dragged, "before", row.dataset.projectPriorityId || ""); });
  });
}

function sharedContextManagerRepositories() {
  return Array.isArray(state.contextHub?.sharedRepositories) ? state.contextHub.sharedRepositories : [];
}

function sharedContextRepositoryLabel(repository) {
  if (repository?.name) return repository.name;
  const parts = String(repository?.repository || "").replace(/\.git$/, "").split(/[/:]/).filter(Boolean);
  return parts.slice(-2).join("/") || "Shared repository";
}

function sharedContextRepositoryConnections(repository) {
  return (state.contextHub?.projects || []).filter((project) => project.mode !== "shared" && project.shared?.repository === repository);
}

function selectedProjectSharedContext() {
  const selected = selectedGlobalProjectSettingsContext();
  return {
    ...selected,
    connection: selected.project?.shared || selected.worktree?.shared || null,
    local: Boolean(selected.project && selected.project.mode !== "shared" && selected.worktree?.root),
  };
}

function renderSharedRepositoryManager() {
  const repositories = sharedContextManagerRepositories();
  const rows = repositories.map((repository) => {
    const connections = sharedContextRepositoryConnections(repository.repository);
    const connected = connections.length;
    const projectCount = Array.isArray(repository.projects) ? repository.projects.length : 0;
    const busy = state.sharedContextManagerBusy ? " disabled" : "";
    const removeDisabled = connected ? " disabled" : busy;
    const removeTitle = connected ? "Disconnect every local project before removing this repository" : "Remove this repository from this device";
    const availability = repository.availability
      || (repository.status?.online ? "online" : (repository.status?.revision ? "cached-offline" : "unavailable"));
    const availabilityLabel = availability === "online"
      ? "Online"
      : availability === "cached-offline"
        ? "Cached offline"
        : "Unavailable or invalid";
    return '<div class="shared-context-repository-row" data-shared-repository="' + escapeHtml(repository.repository) + '">'
      + '<div class="shared-context-repository-copy"><strong>' + escapeHtml(sharedContextRepositoryLabel(repository)) + '</strong><code title="' + escapeHtml(repository.repository) + '">' + escapeHtml(repository.repository) + '</code><span>' + escapeHtml(availabilityLabel) + ' · ' + projectCount + ' shared project' + (projectCount === 1 ? '' : 's') + ' · ' + connected + ' local connection' + (connected === 1 ? '' : 's') + '</span></div>'
      + '<button class="secondary" type="button" data-remove-shared-repository="' + escapeHtml(repository.repository) + '" title="' + escapeHtml(removeTitle) + '"' + removeDisabled + '>Remove</button>'
      + '</div>';
  }).join("");
  return '<div class="shared-context-manager">'
    + '<div class="shared-context-repository-list">' + (rows || '<div class="settings-empty-state"><strong>No shared repositories yet.</strong><span class="settings-empty-state-detail">Add the Git repository that contains accepted shared documentation and proposals.</span></div>') + '</div>'
    + '<div class="shared-context-add-row"><label class="settings-field" for="sharedContextRepositoryInput"><span class="settings-field-title">Git repository</span><span class="settings-field-note">Use an SSH URL, HTTPS URL, or an absolute local Git path.</span><input id="sharedContextRepositoryInput" type="text" autocomplete="off" placeholder="git@github.com:team/context.git" value="' + escapeHtml(state.sharedContextManagerRepositoryDraft || '') + '" /></label><button class="primary" type="button" data-add-shared-repository' + (state.sharedContextManagerBusy ? ' disabled' : '') + '>Add repository</button></div>'
    + '<p class="settings-help">Removing a repository only forgets it on this device. Context Room never deletes the Git repository or its documentation.</p>'
    + '</div>';
}

function renderSharedContextHelpDialog() {
  return '<section class="shared-context-help-dialog" role="dialog" aria-modal="true" aria-labelledby="sharedContextHelpTitle" aria-describedby="sharedContextHelpDescription">'
    + '<header class="shared-context-help-dialog-head"><div class="shared-context-help-dialog-head-copy"><h2 id="sharedContextHelpTitle">Shared Contexts</h2><p id="sharedContextHelpDescription">A Shared Context is a dedicated Git repository that keeps accepted documentation and reusable agent resources separate from the code repository.</p></div><button class="shared-context-help-dialog-close" type="button" data-shared-context-help-close aria-label="Close Shared Context explanation">×</button></header>'
    + '<div class="shared-context-help-dialog-body"><div class="shared-context-help-dialog-sections">'
    + '<section class="shared-context-help-section"><h3>Why it is useful</h3><div class="shared-context-help-grid">'
    + '<div class="shared-context-help-item"><strong>One canonical source</strong><span>Everyone reads the same accepted documentation instead of keeping competing copies in code branches and worktrees.</span></div>'
    + '<div class="shared-context-help-item"><strong>Independent from code</strong><span>Code worktrees can be created, merged, or removed without splitting or deleting the documentation history.</span></div>'
    + '<div class="shared-context-help-item"><strong>Built for collaboration</strong><span>Several people and agents can propose improvements to the same documentation repository.</span></div>'
    + '<div class="shared-context-help-item"><strong>Human-controlled truth</strong><span>Only file changes accepted by a human reach the repository\'s accepted default branch.</span></div>'
    + '</div></section>'
    + '<section class="shared-context-help-section"><h3>What the repository can share</h3><div class="shared-context-help-grid">'
    + '<div class="shared-context-help-item"><strong>Canonical documentation</strong><span>Current project or global documents that agents and humans can use as accepted context.</span></div>'
    + '<div class="shared-context-help-item"><strong>Shared Skills</strong><span>Reusable skill collections assigned to selected projects, worktrees, providers, or the device.</span></div>'
    + '<div class="shared-context-help-item"><strong>Shared Instructions</strong><span>Reviewed instruction files projected to provider-recognized destinations such as AGENTS.md or CLAUDE.md.</span></div>'
    + '<div class="shared-context-help-item"><strong>Several shared projects</strong><span>One repository can organize documentation for multiple logical projects while keeping a single accepted history.</span></div>'
    + '</div><div class="shared-context-help-note"><strong>Hooks stay local</strong><span>Executable hooks are never distributed as shared resources. Context Room keeps them on the machine or inside the local project for safety.</span></div></section>'
    + '<section class="shared-context-help-section"><h3>How changes become accepted</h3><div class="shared-context-help-flow">'
    + '<div class="shared-context-help-step"><strong>Open an edit</strong><span>An agent or teammate works on a separate Git proposal branch and worktree.</span></div>'
    + '<div class="shared-context-help-step"><strong>Review each file</strong><span>The proposal stays outside effective context while a human accepts or rejects its files. An operating agent must ask twice, restating the exact action, scope, and effects before the second separate confirmation.</span></div>'
    + '<div class="shared-context-help-step"><strong>Update the default branch</strong><span>After all required decisions, the proposal is finalized and the accepted branch becomes the new truth.</span></div>'
    + '</div></section>'
    + '<section class="shared-context-help-section"><h3>How Context Room recognizes the shared components</h3><p>The accepted repository declares its own structure. Context Room reads its manifest and mappings instead of guessing from arbitrary folders.</p><div class="shared-context-help-grid">'
    + '<div class="shared-context-help-item"><strong>Repository manifest</strong><span><code>.context-room/shared-repository.json</code> defines the accepted branch and canonical repository paths.</span></div>'
    + '<div class="shared-context-help-item"><strong>Projects</strong><span><code>projects.json</code> maps shared projects to the local projects that consume them.</span></div>'
    + '<div class="shared-context-help-item"><strong>Skills</strong><span><code>skill-locations.json</code> declares skill collections, assignments, providers, and scopes.</span></div>'
    + '<div class="shared-context-help-item"><strong>Instructions</strong><span><code>instruction-locations.json</code> maps reviewed source files to exact provider destinations.</span></div>'
    + '</div></section>'
    + '<section class="shared-context-help-section"><h3>What remains local to each machine</h3><p>Provider availability, device destinations, project overrides, exclusions, caches, and managed-link ownership are local preferences. Context Room only materializes a Skill or Instruction when it can prove the selected provider will discover it, and it never replaces unmanaged files or links.</p></section>'
    + '<section class="shared-context-help-section"><h3>Using several repositories</h3><p>You can register independent Shared Context repositories for different teams, clients, or personal documentation spaces. A local project connects to one shared repository at a time, while every registered repository keeps its own accepted branch, proposals, Shared Skills, and Shared Instructions.</p></section>'
    + '</div></div>'
    + '<footer class="shared-context-help-dialog-footer"><button class="file-action primary" type="button" data-shared-context-help-close>Done</button></footer>'
    + '</section>';
}

function renderSelectedProjectSharedContextManager() {
  const selected = selectedProjectSharedContext();
  if (!selected.local) {
    return '<div class="settings-empty-state"><strong>Select a local project in the Explorer.</strong><span class="settings-empty-state-detail">The selected project can then be connected to one of this device\'s Shared Context repositories.</span></div>';
  }
  const recoveryMarkup = renderContextHubSharedRecoveryNotice(selected.project);
  if (recoveryMarkup) return recoveryMarkup;
  const projectTitle = selected.project.title || selected.project.id;
  if (selected.connection) {
    const repository = sharedContextManagerRepositories().find((item) => item.repository === selected.connection.repository);
    const sharedProject = repository?.projects?.find((item) => item.id === selected.connection.projectId);
    return '<div class="shared-context-connection">'
      + '<div class="shared-context-connection-summary"><span class="context-hub-source" data-source="shared">Connected</span><div><strong>' + escapeHtml(projectTitle) + '</strong><span>' + escapeHtml(sharedProject?.title || selected.connection.projectId) + '</span><code title="' + escapeHtml(selected.connection.repository) + '">' + escapeHtml(selected.connection.repository) + '</code></div></div>'
      + '<div class="shared-context-connection-actions"><p>Accepted documentation comes from this repository\'s configured default branch, normally main. Proposals stay separate until humans finish their file reviews.</p><button class="secondary" type="button" data-disconnect-shared-context' + (state.sharedContextManagerBusy ? ' disabled' : '') + '>Disconnect</button></div>'
      + '</div>';
  }
  const repositories = sharedContextManagerRepositories();
  if (!repositories.length) {
    return '<div class="settings-empty-state"><strong>Add a shared repository first.</strong><span class="settings-empty-state-detail">Then connect ' + escapeHtml(projectTitle) + ' to the matching shared project.</span></div>';
  }
  const requestedRepository = state.sharedContextManagerRepository;
  const repository = repositories.find((item) => item.repository === requestedRepository) || repositories[0];
  state.sharedContextManagerRepository = repository.repository;
  const sharedProjects = Array.isArray(repository.projects) ? repository.projects : [];
  const repositoryOptions = repositories.map((item) => '<option value="' + escapeHtml(item.repository) + '"' + (item.repository === repository.repository ? ' selected' : '') + '>' + escapeHtml(sharedContextRepositoryLabel(item)) + '</option>').join("");
  const projectOptions = '<option value="">Auto-detect from this project</option>' + sharedProjects.map((item) => '<option value="' + escapeHtml(item.id) + '"' + (item.id === state.sharedContextManagerProject ? ' selected' : '') + '>' + escapeHtml(item.title || item.id) + '</option>').join("");
  return '<div class="shared-context-connection-form">'
    + '<div class="shared-context-connection-project"><span>Local project</span><strong>' + escapeHtml(projectTitle) + '</strong><code>' + escapeHtml(contextHubProjectPickerLocation(selected.project)) + '</code></div>'
    + '<label class="settings-field" for="sharedContextRepositorySelect"><span class="settings-field-title">Shared repository</span><select id="sharedContextRepositorySelect">' + repositoryOptions + '</select></label>'
    + '<label class="settings-field" for="sharedContextProjectSelect"><span class="settings-field-title">Shared project</span><select id="sharedContextProjectSelect">' + projectOptions + '</select><span class="settings-field-note">Auto-detect uses the project mapping already declared in the accepted shared repository.</span></label>'
    + '<div class="shared-context-connect-action"><span>One local project connects to one Shared Context repository at a time.</span><button class="primary" type="button" data-connect-shared-context' + (state.sharedContextManagerBusy ? ' disabled' : '') + '>Connect project</button></div>'
    + '</div>';
}

function renderSharedContextManagementSettings() {
  const repositories = sharedContextManagerRepositories();
  const connectionCount = repositories.reduce((total, repository) => total + sharedContextRepositoryConnections(repository.repository).length, 0);
  const globalRecovery = renderContextHubGlobalSharedRecoveryNotice();
  return globalRecovery + '<div class="settings-concept"><strong>Connect each project to one canonical documentation source.</strong><p>Register the Shared Context repositories available on this device, then connect each local project to the right shared project.</p><div class="settings-concept-help"><button id="sharedContextHelpButton" class="settings-concept-help-button" type="button" data-settings-help-trigger aria-haspopup="dialog"><span class="settings-concept-help-icon" aria-hidden="true">i</span>What is a Shared Context?</button></div></div><div class="settings-disclosure-list">'
    + renderSettingsDisclosure({ id: "project-shared-repositories", title: "Shared repositories", copy: "Choose which Shared Context Git repositories this device can browse and manage.", status: repositories.length + " registered", scope: "Device", body: renderSharedRepositoryManager() })
    + renderSettingsDisclosure({ id: "project-shared-connection", title: "Selected project connection", copy: "Connect the selected local project to its matching shared documentation project.", status: connectionCount + " connected", scope: "Project", body: renderSelectedProjectSharedContextManager() })
    + '</div>';
}

function applySharedContextManagerCatalog(catalog, message) {
  if (catalog) applyContextHubMutationCatalog(catalog);
  state.sharedSkillLocations.clear();
  state.sharedInstructionLocations.clear();
  renderGlobalProjectExplorer();
  renderContextRoomGlobalReviewQueue();
  renderSettingsPanel();
  workspaceUpdate("shared-synced");
  setStatus(message);
}

async function addSharedRepositoryFromSettings() {
  if (state.sharedContextManagerBusy) return;
  const repository = String(el("sharedContextRepositoryInput")?.value || state.sharedContextManagerRepositoryDraft || "").trim();
  if (!repository) throw new Error("Enter a Shared Context Git repository");
  state.sharedContextManagerRepositoryDraft = repository;
  state.sharedContextManagerBusy = true;
  renderSettingsPanel();
  try {
    const result = await api("/api/context-hub/shared-repositories", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ repository }) });
    state.sharedContextManagerRepository = result.repository || repository;
    state.sharedContextManagerRepositoryDraft = "";
    applySharedContextManagerCatalog(result.catalog, "shared repository added");
  } finally {
    state.sharedContextManagerBusy = false;
    renderSettingsPanel();
  }
}

async function removeSharedRepositoryFromSettings(repository) {
  if (state.sharedContextManagerBusy) return;
  state.sharedContextManagerBusy = true;
  renderSettingsPanel();
  try {
    const result = await api("/api/context-hub/shared-repositories", { method: "DELETE", headers: { "content-type": "application/json" }, body: JSON.stringify({ repository }) });
    if (state.sharedContextManagerRepository === repository) state.sharedContextManagerRepository = "";
    applySharedContextManagerCatalog(result.catalog, "shared repository removed from this device");
  } finally {
    state.sharedContextManagerBusy = false;
    renderSettingsPanel();
  }
}

async function connectSelectedProjectSharedContext() {
  if (state.sharedContextManagerBusy) return;
  const selected = selectedProjectSharedContext();
  if (!selected.local || !selected.worktree?.id) throw new Error("Select a local project first");
  const repositorySelect = el("sharedContextRepositorySelect");
  const projectSelect = el("sharedContextProjectSelect");
  const repository = String(repositorySelect ? repositorySelect.value : state.sharedContextManagerRepository || "");
  const sharedProjectId = String(projectSelect ? projectSelect.value : state.sharedContextManagerProject || "");
  state.sharedContextManagerBusy = true;
  renderSettingsPanel();
  try {
    const result = await api("/api/context-hub/project-shared-context", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId: selected.worktree.id, repository, sharedProjectId }) });
    applySharedContextManagerCatalog(result.catalog, "project connected to shared context");
  } finally {
    state.sharedContextManagerBusy = false;
    renderSettingsPanel();
  }
}

async function disconnectSelectedProjectSharedContext() {
  if (state.sharedContextManagerBusy) return;
  const selected = selectedProjectSharedContext();
  if (!selected.local || !selected.worktree?.id) throw new Error("Select a local project first");
  state.sharedContextManagerBusy = true;
  renderSettingsPanel();
  try {
    const result = await api("/api/context-hub/project-shared-context", { method: "DELETE", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId: selected.worktree.id }) });
    applySharedContextManagerCatalog(result.catalog, "project disconnected from shared context");
  } finally {
    state.sharedContextManagerBusy = false;
    renderSettingsPanel();
  }
}

function contextHubSharedRecoveryAction(button) {
  if (button?.dataset.recoveryKind === "invalid-journal") {
    const recovery = contextHubGlobalSharedRecovery();
    if (!recovery
      || recovery.quarantineId !== button.dataset.quarantineId
      || recovery.revision !== button.dataset.expectedRevision) {
      throw new Error("This global recovery changed. Refresh Context Room before continuing.");
    }
    return { project: null, recovery, kind: "invalid-journal" };
  }
  const project = (state.contextHub?.projects || []).find((candidate) => candidate.projectKey === button?.dataset.contextHubProjectKey);
  const recovery = contextHubProjectSharedRecovery(project);
  if (!project || !recovery
    || recovery.transactionId !== button?.dataset.transactionId
    || recovery.projectId !== button?.dataset.expectedProjectId
    || recovery.logicalProjectId !== button?.dataset.expectedLogicalProjectId) {
    throw new Error("This recovery changed. Refresh Context Room before continuing.");
  }
  return { project, recovery, kind: "transaction" };
}

async function abandonContextHubSharedRecovery(project, recovery) {
  if (IS_HOSTED_CONTEXT_ROOM) throw new Error("Shared recovery controls are available only in local Context Room.");
  if (state.sharedRecoveryBusy) return;
  const invalidJournal = recovery.kind === "invalid-journal";
  state.sharedRecoveryBusy = invalidJournal ? recovery.quarantineId : recovery.transactionId;
  renderSharedProposalWorkspace();
  if (state.page === "settings") renderSettingsPanel();
  try {
    const result = await api("/api/context-hub/shared-recovery/abandon", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(invalidJournal ? {
        quarantineId: recovery.quarantineId,
        expectedRevision: recovery.revision,
      } : {
        transactionId: recovery.transactionId,
        expectedProjectId: recovery.projectId,
        expectedLogicalProjectId: recovery.logicalProjectId,
      }),
    });
    const nextCatalog = result.catalog ? sanitizeHostedHubCatalog(result.catalog) : state.contextHub;
    applyContextHubMutationCatalog(contextHubCatalogWithoutSharedRecovery(nextCatalog, result.recovery || recovery));
    state.globalProjectExplorerDetails.clear();
    state.globalProjectExplorerErrors.clear();
    workspaceUpdate("shared-recovery-archived");
    const refreshPending = result.refreshPending === true || !result.catalog;
    const remainingInvalidRecoveries = invalidJournal ? contextHubGlobalSharedRecoveries().length : 0;
    const durabilityPending = result.recovery?.durabilityPending === true;
    const orphanCleanup = [
      result.recovery?.orphanBindingRemoved === true ? "orphaned Shared binding removed" : "",
      result.recovery?.canonicalSharedCleared === true ? "matching Hub Shared state cleared" : "",
    ].filter(Boolean).join(" · ");
    const completionStatus = (invalidJournal
      ? "invalid recovery journal archived" + (remainingInvalidRecoveries ? " · " + remainingInvalidRecoveries + " other recovery record" + (remainingInvalidRecoveries === 1 ? " remains" : "s remain") : "")
      : "recovery journal archived" + (orphanCleanup ? " · " + orphanCleanup : "") + " · reconnect " + (project.title || project.id) + " explicitly when ready")
      + (durabilityPending ? " · archive durability confirmation pending" : "");
    const pendingStatus = completionStatus + (refreshPending ? " · Hub refresh pending" : "");
    setStatus(pendingStatus);
    if (refreshPending) void refreshContextHubUi().catch(() => setStatus(pendingStatus + " · retry refresh when ready"));
  } finally {
    state.sharedRecoveryBusy = "";
    renderGlobalProjectExplorer();
    renderContextRoomGlobalReviewQueue();
    renderSharedProposalWorkspace();
    if (state.page === "settings") renderSettingsPanel();
  }
}

function showContextHubAbandonRecoveryDialog(button) {
  let action;
  try {
    action = contextHubSharedRecoveryAction(button);
  } catch (error) {
    setStatus(error.message);
    return;
  }
  if (action.kind === "invalid-journal") {
    const remainingCount = Math.max(0, contextHubGlobalSharedRecoveries().length - 1);
    showConfirmDialog({
      title: "Abandon invalid Context Hub recovery?",
      body: remainingCount
        ? "Archive this quarantined recovery record. Context Hub keeps its current canonical registry. Shared files and Git state remain unchanged. " + remainingCount + " other unreadable recovery record" + (remainingCount === 1 ? " remains" : "s remain") + ", so project and Shared mutations stay blocked until " + (remainingCount === 1 ? "it is" : "they are") + " reviewed."
        : "Archive this quarantined recovery record. Context Hub keeps its current canonical registry. Shared files and Git state remain unchanged. Project and Shared mutations can resume afterward.",
      confirmLabel: "Abandon recovery",
      confirmPendingLabel: "Archiving recovery…",
      onConfirm: () => abandonContextHubSharedRecovery(null, action.recovery),
    });
    return;
  }
  const projectTitle = action.project.title || action.project.id || "this project";
  const shortTransaction = action.recovery.transactionId.slice(0, 12);
  showConfirmDialog({
    title: "Abandon recovery for " + projectTitle + "?",
    body: "Archive recovery transaction " + shortTransaction + ". Context Hub keeps the current canonical state unless every recorded project root is gone; in that orphan-only case it removes the exact Shared binding and clears the matching Hub Shared field. Git files and repository history remain unchanged. Automatic recovery stops, and you must reconnect this project explicitly afterward.",
    confirmLabel: "Abandon recovery",
    confirmPendingLabel: "Archiving recovery…",
    onConfirm: () => abandonContextHubSharedRecovery(action.project, action.recovery),
  });
}

function wireSharedContextManagementSettings(root) {
  root.querySelector("[data-add-shared-repository]")?.addEventListener("click", () => addSharedRepositoryFromSettings().catch((error) => setStatus(error.message)));
  const repositoryInput = root.querySelector("#sharedContextRepositoryInput");
  repositoryInput?.addEventListener("input", (event) => {
    state.sharedContextManagerRepositoryDraft = event.currentTarget.value;
  });
  repositoryInput?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter") return;
    event.preventDefault();
    addSharedRepositoryFromSettings().catch((error) => setStatus(error.message));
  });
  root.querySelectorAll("[data-remove-shared-repository]").forEach((button) => button.addEventListener("click", () => {
    const repository = button.dataset.removeSharedRepository;
    showConfirmDialog({
      title: "Remove shared repository from this device?",
      body: "Context Room will forget this repository locally. The Git repository and all documentation remain untouched.",
      confirmLabel: "Remove repository",
      onConfirm: () => removeSharedRepositoryFromSettings(repository).catch((error) => setStatus(error.message)),
    });
  }));
  root.querySelector("#sharedContextRepositorySelect")?.addEventListener("change", (event) => {
    state.sharedContextManagerRepository = event.currentTarget.value;
    state.sharedContextManagerProject = "";
    renderSettingsPanel();
    window.requestAnimationFrame(() => el("sharedContextRepositorySelect")?.focus());
  });
  root.querySelector("#sharedContextProjectSelect")?.addEventListener("change", (event) => { state.sharedContextManagerProject = event.currentTarget.value; });
  root.querySelector("[data-connect-shared-context]")?.addEventListener("click", () => connectSelectedProjectSharedContext().catch((error) => setStatus(error.message)));
  root.querySelector("[data-disconnect-shared-context]")?.addEventListener("click", () => {
    const selected = selectedProjectSharedContext();
    showConfirmDialog({
      title: "Disconnect " + (selected.project?.title || "this project") + "?",
      body: "Context Room will remove only its managed links and local connection. The shared Git repository, accepted documentation, proposals, and unmanaged files remain untouched.",
      confirmLabel: "Disconnect project",
      onConfirm: () => disconnectSelectedProjectSharedContext().catch((error) => setStatus(error.message)),
    });
  });
}

function renderSnoozedReviewSettings() {
  const reviews = contextRoomSnoozedReviews();
  const rows = reviews.map((item) => {
    const project = contextHubProjectForItem(item);
    const projectLabel = project?.title || item.projectTitle || item.projectId || "Project";
    const title = item.title || item.localFile?.split("/").pop() || item.branch || "Review";
    const detail = item.localFile || item.description || (item.type === "shared" ? "Shared proposal" : "Local review");
    const snooze = contextRoomReviewSnooze(item);
    const search = [projectLabel, title, detail, item.type].filter(Boolean).join(" ").toLowerCase();
    const returns = snooze?.until ? new Date(snooze.until).toLocaleString() : "Later";
    return '<div class="settings-snoozed-row" data-settings-snoozed-row data-settings-snoozed-search="' + escapeHtml(search) + '">'
      + '<div class="settings-snoozed-copy"><div class="settings-snoozed-topline"><span class="context-hub-source" data-source="' + (item.type === "shared" ? "shared" : "local") + '">' + (item.type === "shared" ? "Proposal" : "Local") + '</span><strong>' + escapeHtml(title) + '</strong></div>'
      + '<span>' + escapeHtml(projectLabel) + ' · ' + escapeHtml(detail) + '</span><small>Returns ' + escapeHtml(returns) + '</small></div>'
      + '<button class="secondary" type="button" data-settings-unsnooze-review="' + escapeHtml(item.id) + '">Return now</button></div>';
  }).join("");
  return '<div class="settings-snoozed-tools"><label class="settings-snoozed-search" for="settingsSnoozedReviewSearch"><span>Search snoozed reviews</span><input id="settingsSnoozedReviewSearch" type="search" value="' + escapeHtml(state.settingsSnoozedReviewQuery || "") + '" placeholder="Search by project, file, or proposal…" /></label><span>' + reviews.length + ' pending</span></div>'
    + '<div class="settings-snoozed-list">' + (rows || '<div class="settings-empty-state">No snoozed reviews. Snoozing hides only the exact version you saw; a new version returns to Home immediately.</div>') + '<div class="settings-empty-state" data-settings-snoozed-empty hidden>No snoozed reviews match this search.</div></div>';
}

function wireSnoozedReviewSettings(root) {
  const search = root.querySelector("#settingsSnoozedReviewSearch");
  const filter = () => {
    const query = (search?.value || "").trim().toLowerCase();
    state.settingsSnoozedReviewQuery = search?.value || "";
    let visible = 0;
    root.querySelectorAll("[data-settings-snoozed-row]").forEach((row) => {
      row.hidden = Boolean(query && !row.dataset.settingsSnoozedSearch.includes(query));
      if (!row.hidden) visible += 1;
    });
    const empty = root.querySelector("[data-settings-snoozed-empty]");
    if (empty) empty.hidden = !query || visible > 0;
  };
  search?.addEventListener("input", filter);
  filter();
  root.querySelectorAll("[data-settings-unsnooze-review]").forEach((button) => button.addEventListener("click", () => {
    const item = contextHubReviewItems().find((candidate) => candidate.id === button.dataset.settingsUnsnoozeReview);
    if (item) unsnoozeContextRoomReviews([item]).catch((error) => setStatus(error.message));
  }));
}

function updateSettingsPanelMarkup(holder, markup) {
  const currentShell = holder.querySelector(":scope > .settings-shell");
  const currentTabs = currentShell?.querySelector(":scope > .settings-tabs");
  const currentContent = currentShell?.querySelector(":scope > #settings-content");
  const currentFooter = currentShell?.querySelector(":scope > .settings-footer");
  if (!currentShell || !currentTabs || !currentContent || !currentFooter) {
    holder.innerHTML = markup;
    return;
  }

  const template = document.createElement("template");
  template.innerHTML = markup;
  const nextShell = template.content.firstElementChild;
  const nextContent = nextShell?.querySelector(":scope > #settings-content");
  const nextFooter = nextShell?.querySelector(":scope > .settings-footer");
  if (!nextShell || !nextContent || !nextFooter) {
    holder.innerHTML = markup;
    return;
  }

  // The category tabs are the stable navigation shell. Project settings load
  // asynchronously, so replacing this tablist can detach a button between
  // pointerdown and click (notably in Firefox) and silently lose the user's
  // selection. Refresh only the data-owned content and footer instead.
  currentContent.replaceWith(nextContent);
  currentFooter.replaceWith(nextFooter);
}

