el("globalProjectList")?.addEventListener("keydown", (event) => {
  if (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10")) {
    const row = event.target instanceof Element ? event.target.closest("[data-global-project-key], [data-global-project-folder], [data-global-project-file], [data-computer-explorer-folder], [data-computer-explorer-file]") : null;
    if (row) {
      event.preventDefault();
      row.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, cancelable: true }));
    }
    return;
  }
  const tab = event.target.closest("[data-explorer-document-view]");
  if (!tab || !["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  event.preventDefault();
  const tabs = [...el("globalProjectList").querySelectorAll("[data-explorer-document-view]")];
  const index = tabs.indexOf(tab);
  const next = event.key === "Home"
    ? tabs[0]
    : event.key === "End"
      ? tabs.at(-1)
      : tabs[(index + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length];
  next?.focus();
  next?.click();
});
