document.addEventListener("keydown", (event) => {
  if (!state.sharedProposalWorkspaceOpen) return;
  if (event.key === "Escape") {
    event.preventDefault();
    closeContextRoomSecondaryView();
    return;
  }
  if (event.key === "/" && !["INPUT", "TEXTAREA", "SELECT"].includes(document.activeElement?.tagName)) {
    event.preventDefault();
    el("sharedProposalSearch")?.focus();
    return;
  }
  if (!["j", "k"].includes(event.key) || ["INPUT", "TEXTAREA", "SELECT"].includes(document.activeElement?.tagName)) return;
  const promptMode = state.contextHubView === "codex-prompts";
  const buttons = [...document.querySelectorAll(promptMode ? "[data-codex-prompt-target]" : "[data-context-hub-item]")];
  if (!buttons.length) return;
  event.preventDefault();
  const current = buttons.findIndex((button) => (
    promptMode
      ? button.dataset.codexPromptTarget === state.codexPromptSelection
      : button.dataset.contextHubItem === state.contextHubSelection
  ));
  const offset = event.key === "j" ? 1 : -1;
  const next = buttons[(Math.max(0, current) + offset + buttons.length) % buttons.length];
  const nextItemId = promptMode ? next.dataset.codexPromptTarget : next.dataset.contextHubItem;
  if (promptMode) {
    const selection = selectCodexPromptTarget(nextItemId);
    focusContextHubListItem(nextItemId, { promptMode: true });
    selection.catch((error) => setStatus(error.message))
      .finally(() => focusContextHubListItem(nextItemId, { promptMode: true }));
  } else selectContextHubItem(nextItemId, { restoreFocus: true });
});
